import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, Vector3, Quaternion } = THREE;

  const group = new Group();
  group.position.set(-2.5, 1.6, 0);
  group.rotation.order = 'YXZ';

  // State for interactions
  let isHovered = false;
  let hoveredTimeline = null;
  const activeTimelines = [];

  // Load GLB mesh
  const meshPromise = ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (gltf.scene) {
      group.add(gltf.scene);
    }
    return gltf;
  });

  // Apply cinematic primitive: parallax-scroll
  const parallaxResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.25,
    trigger: 'scroll'
  });
  if (parallaxResult) {
    activeTimelines.push(parallaxResult);
  }

  // Hover effect: rise-in (lift 0.15 units)
  const onHover = () => {
    if (hoveredTimeline) hoveredTimeline.kill();
    isHovered = true;
    hoveredTimeline = gsap.timeline();
    hoveredTimeline.to(
      group.position,
      {
        y: group.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      },
      0
    );
    activeTimelines.push(hoveredTimeline);
  };

  const onHoverOut = () => {
    if (hoveredTimeline) hoveredTimeline.kill();
    isHovered = false;
    hoveredTimeline = gsap.timeline();
    hoveredTimeline.to(
      group.position,
      {
        y: 1.6,
        duration: 0.9,
        ease: 'power4.out'
      },
      0
    );
    activeTimelines.push(hoveredTimeline);
  };

  // Click effect: press-down + emit event
  const onClick = () => {
    const pressTimeline = gsap.timeline();
    pressTimeline.to(
      group.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      },
      0
    );
    pressTimeline.to(
      group.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.3,
        ease: 'power2.out'
      },
      0.12
    );
    activeTimelines.push(pressTimeline);
    ctx.emit('navigate', { to: 'hub-home' });
  };

  // Attach event handlers
  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick
  };

  // Cleanup function
  group.userData.cleanup = () => {
    activeTimelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });
    if (hoveredTimeline && hoveredTimeline.kill) hoveredTimeline.kill();
    if (parallaxResult && parallaxResult.cleanup) parallaxResult.cleanup();

    // Dispose mesh resources
    meshPromise.then((gltf) => {
      if (gltf.scene) {
        gltf.scene.traverse((child) => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((mat) => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        });
      }
    }).catch(() => {});

    group.children.forEach((child) => {
      child.traverse((node) => {
        if (node.geometry) node.geometry.dispose();
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach((mat) => mat.dispose());
          } else {
            node.material.dispose();
          }
        }
      });
    });
  };

  return group;
}
